// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.barcodeimport timber.log.Timberimport com.google.mlkit.vision.barcode.BarcodeScannerimport com.google.mlkit.vision.barcode.BarcodeScannerOptionsimport com.google.mlkit.vision.barcode.BarcodeScanningimport com.google.mlkit.vision.barcode.common.Barcodeimport com.google.mlkit.vision.common.InputImageimport com.roshan.persona.vision.ocr.BoundingBoximport com.roshan.persona.vision.ocr.RgbImageimport com.roshan.persona.vision.ocr.toBitmapimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — ML Kit Barcode Scanner (Module 6 v4 — Step 6.4, REAL implementation). * * Wraps `com.google.mlkit:barcode-scanning` for on-device barcode/QR detection. * Replaces [FakeBarcodeDetectorDelegate] in the Hilt graph. * * ## Supported Formats * * All standard formats — QR, Data Matrix, PDF-417, Aztec, Code-128/39/93, * Codabar, EAN-13/8, ITF, UPC-A/E. UPI QR codes are detected as standard QR * codes; payload parsing (UPI / Pix / PromptPay) is done downstream by * [QrPayloadParser] inside [BarcodeScannerEngine]. * * ## Performance * *  - < 100 ms per frame on mid-range devices (ML Kit on-device). *  - Real-time: 10-15 FPS scanning. * * @see <a href="https://developers.google.com/ml-kit/vision/barcode-scanning/android">ML Kit Barcode Scanning</a> */@Singletonclass MlKitBarcodeScanner @Inject constructor() : BarcodeDetectorDelegate {    /**     * Lazily-built per-format-set scanner cache. ML Kit's [BarcodeScanner]     * is configured at construction time with the formats to scan for; we     * cache one scanner per format-set signature to avoid rebuilding.     */    private val scannerCache = mutableMapOf<String, BarcodeScanner>()    override suspend fun detect(frame: RgbImage, formats: Set<BarcodeFormat>): List<BarcodeResult> {        if (frame.width <= 0 || frame.height <= 0) return emptyList()        val bitmap = try {            frame.toBitmap()        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to convert RgbImage to Bitmap.", t)            return emptyList()        }        return try {            val scanner = scannerFor(formats)            val inputImage = InputImage.fromBitmap(bitmap, 0)            // 10s timeout to prevent ANR if Google Play Services hangs.            val mlBarcodes = com.google.android.gms.tasks.Tasks.await(                scanner.process(inputImage),                10,                java.util.concurrent.TimeUnit.SECONDS,            )            val width = frame.width.toFloat().coerceAtLeast(1f)            val height = frame.height.toFloat().coerceAtLeast(1f)            mlBarcodes.mapNotNull { barcode ->                val rawValue = barcode.rawValue ?: barcode.displayValue                if (rawValue.isNullOrBlank()) return@mapNotNull null                val safeRawValue: String = rawValue  // smart-cast anchor after null check                val rect = barcode.boundingBox                val boundingBox = if (rect != null) {                    val left = (rect.left.toFloat() / width).coerceIn(0f, 0.999f)                    val top = (rect.top.toFloat() / height).coerceIn(0f, 0.999f)                    val right = (rect.right.toFloat() / width).coerceIn(left + 0.001f, 1f)                    val bottom = (rect.bottom.toFloat() / height).coerceIn(top + 0.001f, 1f)                    try {                        BoundingBox(left = left, top = top, right = right, bottom = bottom)                    } catch (iae: IllegalArgumentException) {                        Timber.tag(TAG).w("Skipping barcode with invalid bbox: $rect", iae)                        return@mapNotNull null                    }                } else {                    // No bounding box — default to full image.                    BoundingBox(left = 0f, top = 0f, right = 0.999f, bottom = 0.999f)                }                BarcodeResult(                    format = mapFormat(barcode.format),                    rawValue = safeRawValue,                    boundingBox = boundingBox,                    confidence = DEFAULT_BARCODE_CONFIDENCE,                    payloadType = QrPayloadType.UNKNOWN,  // Parsed downstream by QrPayloadParser.                    parsedPayload = null,                )            }        } catch (t: Throwable) {            Timber.tag(TAG).e("ML Kit BarcodeScanning failed.", t)            emptyList()        } finally {            bitmap.recycle()        }    }    override fun isReady(): Boolean = true    // ─── Internal ──────────────────────────────────────────────────────────    private fun scannerFor(formats: Set<BarcodeFormat>): BarcodeScanner {        val enabledFormats = formats            .mapNotNull { it.toMlKitFormat() }            .ifEmpty { listOf(Barcode.FORMAT_QR_CODE) }            .toIntArray()        val key = enabledFormats.sortedArray().joinToString(",")        return scannerCache.getOrPut(key) {            // ML Kit's setBarcodeFormats(int primary, int... additional) requires            // at least one format. We pass the first as primary and the rest as vararg.            val primary = enabledFormats.first()            val additional = if (enabledFormats.size > 1) {                enabledFormats.copyOfRange(1, enabledFormats.size)            } else {                IntArray(0)            }            val options = BarcodeScannerOptions.Builder()                .setBarcodeFormats(primary, *additional)                .build()            BarcodeScanning.getClient(options)        }    }    private fun BarcodeFormat.toMlKitFormat(): Int? = when (this) {        BarcodeFormat.QR_CODE -> Barcode.FORMAT_QR_CODE        BarcodeFormat.DATA_MATRIX -> Barcode.FORMAT_DATA_MATRIX        BarcodeFormat.PDF_417 -> Barcode.FORMAT_PDF417        BarcodeFormat.AZTEC -> Barcode.FORMAT_AZTEC        BarcodeFormat.CODE_128 -> Barcode.FORMAT_CODE_128        BarcodeFormat.CODE_39 -> Barcode.FORMAT_CODE_39        BarcodeFormat.CODE_93 -> Barcode.FORMAT_CODE_93        BarcodeFormat.CODABAR -> Barcode.FORMAT_CODABAR        BarcodeFormat.EAN_13 -> Barcode.FORMAT_EAN_13        BarcodeFormat.EAN_8 -> Barcode.FORMAT_EAN_8        BarcodeFormat.ITF -> Barcode.FORMAT_ITF        BarcodeFormat.UPC_A -> Barcode.FORMAT_UPC_A        BarcodeFormat.UPC_E -> Barcode.FORMAT_UPC_E        BarcodeFormat.UNKNOWN -> null    }    private fun mapFormat(mlFormat: Int): BarcodeFormat = when (mlFormat) {        Barcode.FORMAT_QR_CODE -> BarcodeFormat.QR_CODE        Barcode.FORMAT_DATA_MATRIX -> BarcodeFormat.DATA_MATRIX        Barcode.FORMAT_PDF417 -> BarcodeFormat.PDF_417        Barcode.FORMAT_AZTEC -> BarcodeFormat.AZTEC        Barcode.FORMAT_CODE_128 -> BarcodeFormat.CODE_128        Barcode.FORMAT_CODE_39 -> BarcodeFormat.CODE_39        Barcode.FORMAT_CODE_93 -> BarcodeFormat.CODE_93        Barcode.FORMAT_CODABAR -> BarcodeFormat.CODABAR        Barcode.FORMAT_EAN_13 -> BarcodeFormat.EAN_13        Barcode.FORMAT_EAN_8 -> BarcodeFormat.EAN_8        Barcode.FORMAT_ITF -> BarcodeFormat.ITF        Barcode.FORMAT_UPC_A -> BarcodeFormat.UPC_A        Barcode.FORMAT_UPC_E -> BarcodeFormat.UPC_E        else -> BarcodeFormat.UNKNOWN    }    private companion object {        private const val TAG = "MlKitBarcodeScanner"        // ML Kit BarcodeScanner doesn't expose per-barcode confidence — it        // either detects a barcode (high confidence) or doesn't. Use 0.95.        private const val DEFAULT_BARCODE_CONFIDENCE = 0.95f    }}